.darma-loader-darma-b17-iron-press { --accent: var(--loader-color, #0891b2); --accent-2: var(--loader-secondary-color, #e2e8f0); width: var(--loader-size, 128px); height: calc(var(--loader-size, 128px) * .58); position: relative; overflow: hidden; }
.darma-loader-darma-b17-iron-press .darma-loader-darma-b17-iron-press__cloth { position: absolute; left: 2%; right: 2%; bottom: 8%; height: 34%; border-radius: 5px; background: repeating-linear-gradient(90deg, color-mix(in srgb, var(--accent-2) 92%, var(--accent)) 0 6%, var(--accent-2) 0 12%); }
.darma-loader-darma-b17-iron-press .darma-loader-darma-b17-iron-press__crease { position: absolute; left: 4%; bottom: 20%; height: 8%; width: 0; border-radius: 3px; background: color-mix(in srgb, var(--accent) 55%, transparent); animation: darma-loader-darma-b17-iron-press-iron-smooth calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
.darma-loader-darma-b17-iron-press .darma-loader-darma-b17-iron-press__iron { position: absolute; left: 4%; bottom: 30%; width: 30%; height: 30%; border-radius: 6px 6px 46% 12%; background: linear-gradient(color-mix(in srgb, #fff 20%, var(--accent)), var(--accent)); animation: darma-loader-darma-b17-iron-press-iron-glide calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
.darma-loader-darma-b17-iron-press .darma-loader-darma-b17-iron-press__iron::after { content: ''; position: absolute; left: 18%; right: 18%; bottom: 96%; height: 46%; border-radius: 999px 999px 0 0; box-shadow: inset 0 4px 0 var(--accent); }
.darma-loader-darma-b17-iron-press i { position: absolute; bottom: 62%; width: 9%; height: 9%; border-radius: 50%; background: color-mix(in srgb, var(--accent-2) 75%, transparent); opacity: 0; animation: darma-loader-darma-b17-iron-press-iron-steam calc(var(--loader-speed, 1s) * 1.3) ease-out infinite, darma-loader-darma-b17-iron-press-iron-glide calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
.darma-loader-darma-b17-iron-press i:nth-of-type(1) { left: 10%; }
.darma-loader-darma-b17-iron-press i:nth-of-type(2) { left: 18%; animation-delay: calc(var(--loader-speed, 1s) * .43), 0s; }
.darma-loader-darma-b17-iron-press i:nth-of-type(3) { left: 26%; animation-delay: calc(var(--loader-speed, 1s) * .86), 0s; }
@keyframes darma-loader-darma-b17-iron-press-iron-glide { 0%, 100% { transform: translateX(0); } 50% { transform: translateX(calc(var(--loader-size, 128px) * .58)); } }
@keyframes darma-loader-darma-b17-iron-press-iron-smooth { 0% { width: 0; opacity: 1; } 50% { width: 62%; opacity: 1; } 92%, 100% { width: 62%; opacity: 0; } }
@keyframes darma-loader-darma-b17-iron-press-iron-steam { 0% { opacity: 0; } 20% { opacity: .85; } 100% { opacity: 0; } }

